-- IATF 16949:2016 compliance database schema and seed
-- Generated from src/data/iatfClauses.ts. Stores clause metadata and paraphrased summaries only.
-- Do not store official standard text unless your organization has the required license.

CREATE EXTENSION IF NOT EXISTS pgcrypto;

CREATE TABLE IF NOT EXISTS iatf_clauses (
  code text PRIMARY KEY,
  title text NOT NULL,
  summary text NOT NULL,
  parent_code text REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE RESTRICT,
  level integer NOT NULL CHECK (level >= 1),
  category text NOT NULL CHECK (category IN ('introduction', 'scope', 'context', 'leadership', 'planning', 'support', 'operation', 'performance', 'improvement')),
  owner_role text NOT NULL,
  audit_weight integer NOT NULL CHECK (audit_weight BETWEEN 1 AND 5),
  csr_relevant boolean NOT NULL DEFAULT false,
  requires_document boolean NOT NULL DEFAULT false,
  recommended_documents jsonb NOT NULL DEFAULT '[]'::jsonb,
  keywords jsonb NOT NULL DEFAULT '[]'::jsonb,
  official_text text NULL,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_iatf_clauses_parent ON iatf_clauses(parent_code);
CREATE INDEX IF NOT EXISTS idx_iatf_clauses_level ON iatf_clauses(level);
CREATE INDEX IF NOT EXISTS idx_iatf_clauses_category ON iatf_clauses(category);
CREATE INDEX IF NOT EXISTS idx_iatf_clauses_csr ON iatf_clauses(csr_relevant);
CREATE INDEX IF NOT EXISTS idx_iatf_clauses_requires_document ON iatf_clauses(requires_document);

CREATE TABLE IF NOT EXISTS clause_requirement_matrix (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  clause_code text NOT NULL REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE CASCADE,
  requirement_type text NOT NULL CHECK (requirement_type IN ('documented_evidence', 'csr_review', 'record_retention', 'audit_evidence')),
  mandatory boolean NOT NULL DEFAULT false,
  requirement_summary text NOT NULL,
  recommended_evidence jsonb NOT NULL DEFAULT '[]'::jsonb,
  priority integer NOT NULL CHECK (priority BETWEEN 1 AND 5),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (clause_code, requirement_type)
);

CREATE TABLE IF NOT EXISTS csr_requirements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  customer_name text NOT NULL,
  csr_code text,
  title text NOT NULL,
  summary text NOT NULL,
  effective_date date,
  status text NOT NULL DEFAULT 'active' CHECK (status IN ('draft', 'active', 'obsolete')),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS csr_clause_mappings (
  csr_requirement_id uuid NOT NULL REFERENCES csr_requirements(id) ON DELETE CASCADE,
  clause_code text NOT NULL REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE RESTRICT,
  mapping_rationale text,
  PRIMARY KEY (csr_requirement_id, clause_code)
);

CREATE TABLE IF NOT EXISTS qms_documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_number text NOT NULL UNIQUE,
  title text NOT NULL,
  document_level text NOT NULL CHECK (document_level IN ('L1', 'L2', 'L3', 'L4')),
  department text NOT NULL,
  owner_name text NOT NULL,
  reviewer_name text,
  approver_name text,
  version_label text NOT NULL,
  lifecycle_status text NOT NULL CHECK (lifecycle_status IN ('Draft', 'Review', 'Approved', 'Obsolete')),
  effective_date date,
  review_due_date date,
  core_tool text,
  security_level text NOT NULL DEFAULT 'Internal',
  storage_uri text,
  checksum_sha256 text,
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS document_clause_mapping (
  document_id uuid NOT NULL REFERENCES qms_documents(id) ON DELETE CASCADE,
  clause_code text NOT NULL REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE RESTRICT,
  evidence_type text NOT NULL DEFAULT 'document' CHECK (evidence_type IN ('document', 'record', 'procedure', 'form', 'external')),
  coverage_status text NOT NULL DEFAULT 'partial' CHECK (coverage_status IN ('covered', 'partial', 'uncovered')),
  notes text,
  mapped_by text,
  mapped_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (document_id, clause_code)
);

CREATE TABLE IF NOT EXISTS audit_readiness_snapshots (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  clause_code text NOT NULL REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE RESTRICT,
  readiness_status text NOT NULL CHECK (readiness_status IN ('ready', 'watch', 'blocked')),
  score integer NOT NULL CHECK (score BETWEEN 0 AND 100),
  open_gap_count integer NOT NULL DEFAULT 0,
  last_assessed_at timestamptz NOT NULL DEFAULT now(),
  assessor text
);

CREATE TABLE IF NOT EXISTS compliance_notifications (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  clause_code text REFERENCES iatf_clauses(code) ON UPDATE CASCADE ON DELETE SET NULL,
  severity text NOT NULL CHECK (severity IN ('info', 'warning', 'critical')),
  title text NOT NULL,
  message text NOT NULL,
  is_resolved boolean NOT NULL DEFAULT false,
  created_at timestamptz NOT NULL DEFAULT now(),
  resolved_at timestamptz
);

CREATE OR REPLACE VIEW document_clause_mappings AS
SELECT * FROM document_clause_mapping;

CREATE OR REPLACE VIEW clause_coverage_summary AS
SELECT
  c.code,
  c.title,
  c.parent_code,
  c.level,
  c.category,
  c.owner_role,
  c.audit_weight,
  c.csr_relevant,
  c.requires_document,
  COUNT(m.document_id) AS mapped_document_count,
  COUNT(m.document_id) FILTER (WHERE d.lifecycle_status = 'Approved') AS approved_document_count,
  CASE
    WHEN COUNT(m.document_id) FILTER (WHERE d.lifecycle_status = 'Approved') > 0 THEN 'covered'
    WHEN COUNT(m.document_id) > 0 THEN 'partial'
    ELSE 'uncovered'
  END AS coverage_status
FROM iatf_clauses c
LEFT JOIN document_clause_mapping m ON m.clause_code = c.code
LEFT JOIN qms_documents d ON d.id = m.document_id
WHERE split_part(c.code, '.', 1)::int >= 4
GROUP BY c.code, c.title, c.parent_code, c.level, c.category, c.owner_role, c.audit_weight, c.csr_relevant, c.requires_document;

ON CONFLICT (code) DO UPDATE SET
  title = EXCLUDED.title,
  summary = EXCLUDED.summary,
  parent_code = EXCLUDED.parent_code,
  level = EXCLUDED.level,
  category = EXCLUDED.category,
  owner_role = EXCLUDED.owner_role,
  audit_weight = EXCLUDED.audit_weight,
  csr_relevant = EXCLUDED.csr_relevant,
  requires_document = EXCLUDED.requires_document,
  recommended_documents = EXCLUDED.recommended_documents,
  keywords = EXCLUDED.keywords,
  updated_at = now();

ON CONFLICT (clause_code, requirement_type) DO UPDATE SET
  mandatory = EXCLUDED.mandatory,
  requirement_summary = EXCLUDED.requirement_summary,
  recommended_evidence = EXCLUDED.recommended_evidence,
  priority = EXCLUDED.priority,
  updated_at = now();
